736	+//! Tests for typed (native Anthropic) tools on the forced-tool path.
737	+
738	+use insta::assert_json_snapshot;
739	+use paigasus_helikon_core::{
740	+    ContentPart, Item, ModelError, ModelRequest, ProviderToolType, ResponseFormat, ToolChoice,
741	+    ToolDef,
742	+};
743	+use serde_json::{json, Value};
744	+
745	+use crate::builder::Config;
746	+use crate::policy::OutputPath;
747	+use crate::translate::tools::{PLACEHOLDER_DESCRIPTION, SYNTHESIZED_TOOL_NAME};
748	+use crate::translate::{build_request, to_wire_json, PreparedConverse};
749	+
750	+const FORCED_ID: &str = "us.anthropic.claude-sonnet-4-6";
751	+// remove in Task 5: no caller yet.
752	+#[allow(dead_code)]
753	+const NATIVE_ID: &str = "us.anthropic.claude-sonnet-5-5";
754	+const NOVA_ID: &str = "us.amazon.nova-pro-v1:0";
755	+
756	+pub(super) fn memory_tool() -> ToolDef {
757	+    ToolDef::new("memory", "Memory", json!({"type": "object"}))
758	+        .with_provider_types(vec![ProviderToolType::new("anthropic", "memory_20250818")])
759	+}
760	+
761	+pub(super) fn balance_tool() -> ToolDef {
762	+    ToolDef::new(
763	+        "get_balance",
764	+        "Get account balance",
765	+        json!({"type": "object", "properties": {"account_id": {"type": "string"}}}),
766	+    )
767	+}
768	+
769	+fn text(t: &str) -> Vec<ContentPart> {
770	+    vec![ContentPart::Text { text: t.to_owned() }]
771	+}
772	+
773	+/// A user turn, one `memory` call and its result.
774	+pub(super) fn memory_round() -> Vec<Item> {
775	+    vec![
776	+        Item::UserMessage {
777	+            content: text("Remember this."),
778	+        },
779	+        Item::AssistantMessage {
780	+            content: vec![ContentPart::ToolUse {
781	+                call_id: "tu_1".to_owned(),
782	+                name: "memory".to_owned(),
783	+                args: json!({"command": "view", "path": "/memories"}),
784	+            }],
785	+            agent: None,
786	+        },
787	+        Item::ToolResult {
788	+            call_id: "tu_1".to_owned(),
789	+            content: text("empty"),
790	+        },
791	+    ]
792	+}
793	+
794	+pub(super) fn cfg(id: &str) -> Config {
795	+    crate::builder::offline_config(id)
796	+}
797	+
798	+pub(super) fn forced(cfg: &Config, req: &ModelRequest) -> Result<PreparedConverse, ModelError> {
799	+    build_request(cfg, req, OutputPath::ForcedTool)
800	+}
801	+
802	+// remove in Task 5: no caller yet.
803	+#[allow(dead_code)]
804	+pub(super) fn native(cfg: &Config, req: &ModelRequest) -> Result<PreparedConverse, ModelError> {
805	+    build_request(cfg, req, OutputPath::Native)
806	+}
807	+
808	+pub(super) fn tool_names(w: &Value) -> Vec<String> {
809	+    w["toolConfig"]["tools"]
810	+        .as_array()
811	+        .map(|a| {
812	+            a.iter()
813	+                .map(|t| t["toolSpec"]["name"].as_str().unwrap().to_owned())
814	+                .collect()
815	+        })
816	+        .unwrap_or_default()
817	+}
818	+
819	+fn first_turn(tools: Vec<ToolDef>) -> ModelRequest {
820	+    let mut req = ModelRequest::new();
821	+    req.messages = vec![Item::UserMessage {
822	+        content: text("Hello"),
823	+    }];
824	+    req.tools = tools;
825	+    req
826	+}
827	+
828	+fn round(tools: Vec<ToolDef>) -> ModelRequest {
829	+    let mut req = ModelRequest::new();
830	+    req.messages = memory_round();
831	+    req.tools = tools;
832	+    req
833	+}
834	+
835	+fn typed_entry() -> Value {
836	+    json!({"type": "memory_20250818", "name": "memory"})
837	+}
838	+
839	+fn err_text(r: Result<PreparedConverse, ModelError>) -> String {
840	+    format!("{}", r.unwrap_err())
841	+}
