843	+#[test]
844	+fn snap_typed_only_first_turn() {
845	+    let p = forced(&cfg(FORCED_ID), &first_turn(vec![memory_tool()])).unwrap();
846	+    let w = to_wire_json(&p);
847	+    assert!(w["toolConfig"].is_null());
848	+    assert_eq!(
849	+        w["additionalModelRequestFields"],
850	+        json!({"tools": [typed_entry()]})
851	+    );
852	+    assert_json_snapshot!(w);
853	+}
854	+
855	+#[test]
856	+fn snap_typed_and_generic() {
857	+    let p = forced(
858	+        &cfg(FORCED_ID),
859	+        &first_turn(vec![memory_tool(), balance_tool()]),
860	+    )
861	+    .unwrap();
862	+    let w = to_wire_json(&p);
863	+    assert_eq!(tool_names(&w), vec!["get_balance".to_owned()]);
864	+    assert!(w["toolConfig"]["toolChoice"].is_null());
865	+    assert_eq!(
866	+        w["additionalModelRequestFields"]["tools"],
867	+        json!([typed_entry()])
868	+    );
869	+    assert_json_snapshot!(w);
870	+}
